/**
 * TypeScript Compiler Service for Node-RED
 * Handles TypeScript compilation with userDir module resolution
 */

const ts = require("typescript");
const path = require("path");
const fs = require("fs-extra");
const Module = require("module");

class TypeScriptCompiler {
    constructor(userDir) {
        this.userDir = userDir;
        console.log(`[TS-Compiler] Initializing TypeScript compiler for userDir: ${userDir}`);
        
        this.compilerHost = this.createCompilerHost();
        
        // Cache compiled modules
        this.compiledCache = new Map();
        
        // Default library files
        this.defaultLibs = this.loadDefaultLibs();
        
        console.log(`[TS-Compiler] TypeScript compiler initialized`);
    }

    /**
     * Create a custom TypeScript compiler host
     */
    createCompilerHost() {
        console.log('[TS-Compiler] Creating custom compiler host...');
        
        const host = ts.createCompilerHost({
            target: ts.ScriptTarget.ES2020,
            module: ts.ModuleKind.CommonJS,
            moduleResolution: ts.ModuleResolutionKind.NodeJs,
            lib: ['lib.es2020.d.ts'],
            skipLibCheck: true
        });
        
        // Store original methods
        const originalFileExists = host.fileExists;
        const originalReadFile = host.readFile;
        const originalGetSourceFile = host.getSourceFile;
        
        // Override fileExists to check userDir
        host.fileExists = (fileName) => {
            console.log(`[TS-Compiler] Checking if file exists: ${fileName}`);
            
            // Handle virtual function file
            if (fileName === "virtual-function.ts") {
                return true;
            }
            
            // Check userDir paths
            if (fileName.includes('@userDir/')) {
                const userDirPath = fileName.replace(/@userDir\//, '');
                const fullPath = path.resolve(this.userDir, userDirPath);
                const exists = fs.existsSync(fullPath);
                console.log(`[TS-Compiler] UserDir file ${fileName} -> ${fullPath} exists: ${exists}`);
                return exists;
            }
            
            const exists = originalFileExists.call(host, fileName);
            console.log(`[TS-Compiler] System file ${fileName} exists: ${exists}`);
            return exists;
        };
        
        // Override readFile to read from userDir
        host.readFile = (fileName) => {
            console.log(`[TS-Compiler] Reading file: ${fileName}`);
            
            // Handle userDir paths
            if (fileName.includes('@userDir/')) {
                const userDirPath = fileName.replace(/@userDir\//, '');
                const fullPath = path.resolve(this.userDir, userDirPath);
                if (fs.existsSync(fullPath)) {
                    const content = fs.readFileSync(fullPath, 'utf8');
                    console.log(`[TS-Compiler] Read userDir file ${fileName} (${content.length} chars)`);
                    return content;
                }
            }
            
            const content = originalReadFile.call(host, fileName);
            if (content) {
                console.log(`[TS-Compiler] Read system file ${fileName} (${content.length} chars)`);
            }
            return content;
        };
        
        // Override getSourceFile for better control
        host.getSourceFile = (fileName, languageVersion, onError, shouldCreateNewSourceFile) => {
            console.log(`[TS-Compiler] Getting source file: ${fileName}`);
            
            // Handle virtual function file - return undefined to let TypeScript handle it
            if (fileName === "virtual-function.ts") {
                return undefined;
            }
            
            // Handle userDir imports - for now, ignore them to avoid resolution issues
            if (fileName.includes('@userDir/')) {
                console.log(`[TS-Compiler] Skipping userDir import: ${fileName}`);
                return undefined;
            }
            
            return originalGetSourceFile.call(host, fileName, languageVersion, onError, shouldCreateNewSourceFile);
        };
        
        // Simplified module resolution - avoid complex userDir resolution for now
        host.resolveModuleNames = (moduleNames, containingFile, reusedNames, redirectedReference, options) => {
            console.log(`[TS-Compiler] Resolving modules:`, moduleNames, 'from:', containingFile);
            
            const resolvedModules = [];
            
            for (const moduleName of moduleNames) {
                // For @userDir imports, return undefined to avoid resolution issues
                if (moduleName.startsWith('@userDir/')) {
                    console.log(`[TS-Compiler] Skipping userDir module resolution: ${moduleName}`);
                    resolvedModules.push(undefined);
                } else {
                    // Use TypeScript's default resolution for other modules
                    console.log(`[TS-Compiler] Using default resolution for: ${moduleName}`);
                    const result = ts.resolveModuleName(moduleName, containingFile, options, host);
                    resolvedModules.push(result.resolvedModule);
                    
                    if (result.resolvedModule) {
                        console.log(`[TS-Compiler] Resolved ${moduleName} to ${result.resolvedModule.resolvedFileName}`);
                    } else {
                        console.warn(`[TS-Compiler] Failed to resolve module: ${moduleName}`);
                    }
                }
            }
            
            return resolvedModules;
        };
        
        console.log('[TS-Compiler] Custom compiler host created');
        return host;
    }

    /**
     * Load TypeScript default library files
     */
    loadDefaultLibs() {
        console.log('[TS-Compiler] Loading default TypeScript libraries...');
        
        const libs = new Map();
        
        try {
            const libPath = path.dirname(require.resolve('typescript'));
            
            // Load essential lib files
            const libFiles = [
                'lib.es5.d.ts',
                'lib.es2015.d.ts',
                'lib.es2020.d.ts',
                'lib.dom.d.ts',
                'lib.webworker.d.ts'
            ];
            
            for (const libFile of libFiles) {
                try {
                    const libFilePath = path.join(libPath, libFile);
                    if (fs.existsSync(libFilePath)) {
                        const content = fs.readFileSync(libFilePath, 'utf8');
                        libs.set(libFile, content);
                        console.log(`[TS-Compiler] Loaded lib: ${libFile}`);
                    }
                } catch (err) {
                    console.warn(`[TS-Compiler] Failed to load TypeScript lib file: ${libFile}`, err.message);
                }
            }
            
            console.log(`[TS-Compiler] Loaded ${libs.size} default libraries`);
        } catch (err) {
            console.error('[TS-Compiler] Failed to load default TypeScript libraries:', err);
        }
        
        return libs;
    }

    /**
     * Compile TypeScript code
     */
    compile(code, options, callback) {
        console.log('[TS-Compiler] Starting TypeScript compilation...');
        console.log('[TS-Compiler] Code length:', code.length);
        
        try {
            // Simple compilation for Node-RED function nodes
            const compilerOptions = {
                target: ts.ScriptTarget.ES2020,
                module: ts.ModuleKind.None, // Don't generate module code
                moduleResolution: ts.ModuleResolutionKind.NodeJs,
                esModuleInterop: true,
                allowSyntheticDefaultImports: true,
                strict: false,
                noImplicitAny: false,
                skipLibCheck: true,
                allowJs: true,
                noResolve: true, // Skip module resolution to avoid errors
                isolatedModules: false, // Allow non-module compilation
                suppressOutputPathCheck: true
            };
            
            console.log('[TS-Compiler] Using simple compiler options');
            
            // Simple transpilation using transpileModule
            const result = ts.transpileModule(code, {
                compilerOptions: compilerOptions,
                moduleName: 'functionNode'
            });
            
            console.log('[TS-Compiler] Transpilation completed successfully');
            
            const compilationResult = {
                outputText: result.outputText || '',
                errors: [],
                warnings: 0,
                success: true
            };
            
            // Check for basic syntax errors
            if (result.diagnostics && result.diagnostics.length > 0) {
                const errors = result.diagnostics
                    .filter(d => d.category === ts.DiagnosticCategory.Error)
                    .map(diagnostic => {
                        const message = ts.flattenDiagnosticMessageText(diagnostic.messageText, '\n');
                        return {
                            line: diagnostic.start ? ts.getLineAndCharacterOfPosition(diagnostic.file || ts.createSourceFile('temp.ts', code, ts.ScriptTarget.ES2020), diagnostic.start).line + 1 : 1,
                            column: diagnostic.start ? ts.getLineAndCharacterOfPosition(diagnostic.file || ts.createSourceFile('temp.ts', code, ts.ScriptTarget.ES2020), diagnostic.start).character + 1 : 1,
                            message: message,
                            code: diagnostic.code
                        };
                    });
                
                compilationResult.errors = errors;
                compilationResult.success = errors.length === 0;
            }
            
            console.log('[TS-Compiler] Compilation result:', {
                success: compilationResult.success,
                outputLength: compilationResult.outputText.length,
                errorCount: compilationResult.errors.length
            });
            
            callback(null, compilationResult);
            
        } catch (error) {
            console.error('[TS-Compiler] Compilation error:', error);
            
            // Fallback: return the original code if compilation fails
            const fallbackResult = {
                outputText: code,
                errors: [{
                    line: 1,
                    column: 1,
                    message: `TypeScript compilation failed: ${error.message}`,
                    code: 0
                }],
                warnings: 0,
                success: false
            };
            
            callback(null, fallbackResult);
        }
    }

    /**
     * Get available types in userDir
     */
    getAvailableTypes(callback) {
        console.log('[TS-Compiler] Getting available types...');
        
        try {
            const types = {
                userDirModules: [],
                installedPackages: []
            };
            
            // Scan userDir for TypeScript files
            const scanDir = (dir, prefix = '') => {
                if (!fs.existsSync(dir)) {
                    console.log(`[TS-Compiler] Directory does not exist: ${dir}`);
                    return;
                }
                
                console.log(`[TS-Compiler] Scanning directory: ${dir}`);
                
                const files = fs.readdirSync(dir);
                for (const file of files) {
                    const fullPath = path.join(dir, file);
                    const stat = fs.statSync(fullPath);
                    
                    if (stat.isDirectory() && !file.startsWith('.') && file !== 'node_modules') {
                        scanDir(fullPath, prefix + file + '/');
                    } else if (file.endsWith('.ts') || file.endsWith('.tsx')) {
                        const modulePath = '@userDir/' + prefix + file.replace(/\.(ts|tsx)$/, '');
                        types.userDirModules.push({
                            path: modulePath,
                            file: fullPath
                        });
                        console.log(`[TS-Compiler] Found TypeScript module: ${modulePath}`);
                    }
                }
            };
            
            scanDir(this.userDir);
            
            // Check for installed @types packages
            const nodeModulesPath = path.join(this.userDir, 'node_modules', '@types');
            if (fs.existsSync(nodeModulesPath)) {
                const typePackages = fs.readdirSync(nodeModulesPath);
                types.installedPackages = typePackages.map(pkg => '@types/' + pkg);
                console.log(`[TS-Compiler] Found ${types.installedPackages.length} @types packages`);
            }
            
            console.log(`[TS-Compiler] Available types: ${types.userDirModules.length} userDir modules, ${types.installedPackages.length} installed packages`);
            
            callback(null, types);
        } catch (error) {
            console.error('[TS-Compiler] Error getting available types:', error);
            callback(error);
        }
    }

    /**
     * Watch userDir for changes
     */
    watchUserDir(onChange) {
        console.log(`[TS-Compiler] Starting to watch userDir: ${this.userDir}`);
        
        const watcher = fs.watch(this.userDir, { recursive: true }, (eventType, filename) => {
            if (filename && (filename.endsWith('.ts') || filename.endsWith('.tsx'))) {
                console.log(`[TS-Compiler] File changed: ${filename} (${eventType})`);
                
                // Clear cache for changed file
                this.compiledCache.delete(filename);
                onChange(eventType, filename);
            }
        });
        
        return watcher;
    }
}

module.exports = TypeScriptCompiler;